using System;
using System.IO;
using System.Text;
using System.Web.Script.Serialization;

internal static class VisualTweaksVerification {
    static void Require(bool condition,string message){if(!condition)throw new Exception(message);}
    static void Reject(Action action,string message){bool failed=false;try{action();}catch(InvalidOperationException){failed=true;}Require(failed,message);}
    static bool Same(byte[] a,byte[] b){return IntroTweaks.Hash(a)==IntroTweaks.Hash(b);}
    internal static void Run(string root){
        string folder=Path.Combine(Path.GetTempPath(),"A2HVisualTests",Guid.NewGuid().ToString("N")),config=Path.Combine(folder,"AION2","Saved_Steam","Config","Windows","Engine.ini"),backup=Path.Combine(folder,"private-backups"),prefs=Path.Combine(folder,"prefs");Directory.CreateDirectory(Path.GetDirectoryName(config));Directory.CreateDirectory(prefs);
        string original="; keep this comment\r\n[Core.System]\r\nPaths=../One\r\nPaths=../Two\r\n\r\n"+VisualTweaks.Section+"\r\nr.ngx.dlss.enable=1\r\nr.fidelityfx.fsr.enabled=0\r\n";
        var utf8=new UTF8Encoding(false,true);byte[] bytes=utf8.GetBytes(original);File.WriteAllBytes(config,bytes);bool running=false;var service=new VisualTweaks(prefs,backup,delegate{return running;});service.ChooseFile(config);
        Require(Same(bytes,File.ReadAllBytes(config)),"Choosing config must not change it");var state=service.Inspect();Require(state.Found&&state.CanApply&&Array.TrueForAll(state.Enabled,delegate(bool b){return b;}),"Unmodified INI reports actual game defaults without writing overrides");service.Apply(new[]{true,true,true,true,true},service.Snapshot());Require(Same(bytes,File.ReadAllBytes(config))&&!Directory.Exists(backup),"All-on apply is a byte-exact no-op and creates no backup");
        service.Apply(new[]{false,true,true,true,true},service.Snapshot());string disabled=File.ReadAllText(config);Require(disabled.StartsWith(original)&&disabled.EndsWith("r.DepthOfFieldQuality=0\r\n")&&!disabled.Contains("r.MotionBlurQuality"),"Only chosen effect changes; paths and DLSS/FSR retained");Require((File.GetAttributes(config)&FileAttributes.ReadOnly)==0,"INI remains writable");Require(service.Inspect().CanRestore,"Verified backup allows restore");service.Restore();Require(Same(bytes,File.ReadAllBytes(config)),"Restore byte-exact initial INI");
        // Multiple sections, commented keys, custom quality values, dithering and other-section keys survive.
        string custom=original+"r.DepthOfFieldQuality=3 ; quality\r\n; r.MotionBlurQuality=0\r\nr.Tonemapper.GrainQuantization=0\r\n"+VisualTweaks.Section.ToUpperInvariant()+"\r\nR.DEPTHOFFIELDQUALITY=2\r\n[Other]\r\nr.DepthOfFieldQuality=7\r\n";
        File.WriteAllText(config,custom,utf8);service.Apply(new[]{true,true,false,true,true},service.Snapshot());Require(File.ReadAllText(config).Contains("r.DepthOfFieldQuality=3 ; quality")&&File.ReadAllText(config).Contains("R.DEPTHOFFIELDQUALITY=2"),"Unchanged effect preserves custom values and duplicates");service.Apply(new[]{false,true,false,true,true},service.Snapshot());string modified=File.ReadAllText(config);Require(modified.Contains("r.DepthOfFieldQuality=0 ; quality")&&!modified.Contains("R.DEPTHOFFIELDQUALITY=")&&modified.Contains("[Other]\r\nr.DepthOfFieldQuality=7")&&modified.Contains("r.Tonemapper.GrainQuantization=0"),"Case insensitive scoped edits consolidate only managed duplicates; dithering untouched");
        // Unreal/user changing unrelated lines after our edit must be preserved by restore.
        File.AppendAllText(config,"NewOtherValue=42\r\n",utf8);service.Restore();string merged=File.ReadAllText(config);Require(merged.Contains("NewOtherValue=42")&&merged.Contains("R.DEPTHOFFIELDQUALITY=2")&&merged.Contains("r.DepthOfFieldQuality=3 ; quality"),"Restore preserves unrelated subsequent edits and restores previous managed lines");
        var current=service.Snapshot();File.AppendAllText(config,"Another=1\r\n",utf8);byte[] changed=File.ReadAllBytes(config);Reject(delegate{service.Apply(new[]{false,false,false,false,false},current);},"Stale UI snapshot is rejected");Require(Same(changed,File.ReadAllBytes(config)),"Stale apply never overwrites new game edits");
        running=true;Reject(delegate{service.Apply(new[]{false,false,false,false,false},service.Snapshot());},"Game open blocks apply");Reject(service.Restore,"Game open blocks restore");running=false;
        File.SetAttributes(config,File.GetAttributes(config)|FileAttributes.ReadOnly);Reject(delegate{service.Apply(new[]{false,false,false,false,false},service.Snapshot());},"Read-only INI never modified");File.SetAttributes(config,File.GetAttributes(config)&~FileAttributes.ReadOnly);
        var encodings=new Encoding[]{new UTF8Encoding(false,true),new UTF8Encoding(true,true),new UnicodeEncoding(false,true,true),new UnicodeEncoding(true,true,true),Encoding.GetEncoding(1252)};
        foreach(var encoding in encodings)foreach(string ending in new[]{"\r\n","\n"}){
            string text=(original+"; café\r\n").Replace("\r\n",ending).TrimEnd('\r','\n');File.WriteAllText(config,text,encoding);byte[] baseBytes=File.ReadAllBytes(config);Require(Same(baseBytes,new VisualTweaks.Ini(baseBytes).Bytes()),"Encoding/newline/no-final-newline round trip");service.Apply(new[]{false,false,false,false,false},service.Snapshot());byte[] output=File.ReadAllBytes(config);Require(encoding.GetPreamble().Length==0||output[0]==encoding.GetPreamble()[0],"BOM retained");var flags=service.Inspect().Enabled;Require(!flags[0]&&!flags[1]&&!flags[2]&&!flags[3]&&!flags[4],"All five independently off");service.Restore();Require(Same(baseBytes,File.ReadAllBytes(config)),"Exact backup restoration for every encoding");
        }
        File.WriteAllText(config,"[Core.System]\nPaths=One",utf8);service.Apply(new[]{true,false,true,true,true},service.Snapshot());Require(File.ReadAllText(config)=="[Core.System]\nPaths=One\n"+VisualTweaks.Section+"\nr.SceneColorFringeQuality=0","Missing renderer section is appended without replacing original");service.Apply(new[]{true,true,true,true,true},service.Snapshot());Require(service.Inspect().Enabled[1]&&!File.ReadAllText(config).Contains("r.SceneColorFringeQuality"),"Enabling removes override instead of inventing quality");
        // Outline uses the tested SystemSettings override; no effect on the other choices.
        File.WriteAllBytes(config,bytes);service.Apply(new[]{true,true,true,true,false},service.Snapshot());string outline=File.ReadAllText(config);
        Require(outline==original+VisualTweaks.SystemSection+"\r\nr.CustomDepth=0\r\n"&&!service.Inspect().Enabled[4],"Outline alone adds the tested SystemSettings override");
        Require(Array.TrueForAll(new[]{service.Inspect().Enabled[0],service.Inspect().Enabled[1],service.Inspect().Enabled[2],service.Inspect().Enabled[3]},delegate(bool b){return b;}),"Outline does not alter other effects");
        File.AppendAllText(config,"r.Unrelated=7\r\n",utf8);service.Restore();Require(!File.ReadAllText(config).Contains("r.CustomDepth")&&File.ReadAllText(config).Contains("r.Unrelated=7"),"Merged outline restore preserves later settings");
        service.Apply(new[]{true,true,true,true,false},service.Snapshot());service.Apply(new[]{true,true,true,true,true},service.Snapshot());Require(!File.ReadAllText(config).Contains("r.CustomDepth="),"Enabling outline removes override and does not force a mode");
        // Custom settings in both supported scopes: SystemSettings wins even if it occurs first.
        string scoped="[SystemSettings]\nR.CustomDepth=0 ; disabled\n"+VisualTweaks.Section+"\nr.CustomDepth=3\n[Other]\nr.CustomDepth=0\n";
        Require(!new VisualTweaks.Ini(utf8.GetBytes(scoped)).Enabled()[4],"SystemSettings override takes precedence over RendererSettings");
        string customOutline=scoped.Replace("R.CustomDepth=0 ; disabled","R.CustomDepth=2 ; custom");File.WriteAllText(config,customOutline,utf8);
        service.Apply(new[]{true,true,true,true,false},service.Snapshot());string customOff=File.ReadAllText(config);
        Require(customOff.Contains("[SystemSettings]\nr.CustomDepth=0\n")&&!customOff.Contains("r.CustomDepth=3")&&customOff.Contains("[Other]\nr.CustomDepth=0"),"Disabling consolidates supported outline overrides and preserves other sections");
        File.AppendAllText(config,"Keep=9\n",utf8);service.Restore();string restoredOutline=File.ReadAllText(config);
        Require(restoredOutline.Contains("[SystemSettings]\nR.CustomDepth=2 ; custom\n")&&restoredOutline.Contains(VisualTweaks.Section+"\nr.CustomDepth=3\n")&&restoredOutline.Contains("Keep=9"),"Merged restore returns custom outline modes to original sections");
        // A v1 backup only owned the original four keys; it must not remove a later outline choice.
        File.WriteAllBytes(config,bytes);service.Apply(new[]{false,true,true,true,true},service.Snapshot());string journal=Directory.GetFiles(backup,"last-change.json",SearchOption.AllDirectories)[0];
        var serializer=new JavaScriptSerializer();var legacy=serializer.Deserialize<VisualTweaks.Record>(File.ReadAllText(journal));legacy.Version=1;legacy.ManagedHash=new VisualTweaks.Ini(service.Snapshot()).ManagedHash(4);File.WriteAllText(journal,serializer.Serialize(legacy),utf8);
        Require(service.Inspect().CanRestore,"Version 1 backup still recognized");service.Restore();Require(Same(bytes,File.ReadAllBytes(config)),"Version 1 exact restore remains byte exact");
        service.Apply(new[]{false,true,true,true,true},service.Snapshot());legacy=serializer.Deserialize<VisualTweaks.Record>(File.ReadAllText(journal));legacy.Version=1;legacy.ManagedHash=new VisualTweaks.Ini(service.Snapshot()).ManagedHash(4);File.WriteAllText(journal,serializer.Serialize(legacy),utf8);
        File.AppendAllText(config,"[SystemSettings]\r\nr.CustomDepth=0\r\nKeep=12\r\n",utf8);Require(service.Inspect().CanRestore,"Legacy backup ignores newly supported outline override");service.Restore();
        Require(File.ReadAllText(config).Contains("r.CustomDepth=0")&&File.ReadAllText(config).Contains("Keep=12")&&!File.ReadAllText(config).Contains("r.DepthOfFieldQuality="),"Legacy merged restore owns four effects only");
        File.WriteAllBytes(config,bytes);service.Apply(new[]{true,true,true,true,false},service.Snapshot());File.AppendAllText(config,"r.CustomDepth=3\r\n",utf8);Reject(service.Restore,"New backups detect external outline changes");
        File.WriteAllBytes(config,bytes);int checks=0;var late=new VisualTweaks(prefs,backup,delegate{return ++checks>=2;});Reject(delegate{late.Apply(new[]{false,false,false,false,false},late.Snapshot());},"Game starting during apply blocks replacement");Require(Same(bytes,File.ReadAllBytes(config)),"Late game start preserves INI");
        int changeChecks=0;var concurrent=new VisualTweaks(prefs,backup,delegate{if(++changeChecks==2)File.AppendAllText(config,"; concurrent\r\n",utf8);return false;});Reject(delegate{concurrent.Apply(new[]{false,false,false,false,false},concurrent.Snapshot());},"Concurrent file change blocks replacement");Require(File.ReadAllText(config).EndsWith("; concurrent\r\n"),"Concurrent edit preserved");
        File.WriteAllBytes(config,bytes);service.Apply(new[]{false,true,true,true,true},service.Snapshot());File.AppendAllText(config,"r.FilmGrain=0\r\n",utf8);Reject(service.Restore,"External managed changes prevent restore");
        File.WriteAllBytes(config,bytes);service.Apply(new[]{false,true,true,true,true},service.Snapshot());string[] backups=Directory.GetFiles(backup,"*.ini",SearchOption.AllDirectories);foreach(string file in backups)if(IntroTweaks.Hash(File.ReadAllBytes(file))==IntroTweaks.Hash(bytes))File.WriteAllText(file,"damaged");Reject(service.Restore,"Corrupted backup rejected");
        File.WriteAllBytes(config,bytes);string second=Path.Combine(folder,"AION2","Saved_TW","Config","Windows","Engine.ini");Directory.CreateDirectory(Path.GetDirectoryName(second));File.WriteAllBytes(second,bytes);Require(VisualTweaks.FindFiles(Path.Combine(folder,"AION2")).Length==2,"Steam and non-Steam discovery both found for explicit choice");Require(VisualTweaks.FindFiles(Path.Combine(folder,"missing")).Length==0,"Missing config supports manual fallback");
        // UI uses only fixtures; no live game config is changed by verification.
        var uiService=new VisualTweaks(Path.Combine(folder,"fresh-ui-prefs"),Path.Combine(folder,"ui-backups"),delegate{return false;});uiService.ChooseFile(config);Require(uiService.Inspect().Enabled[4],"Fresh UI defaults outline on without editing the game config");using(var owner=new EnergyOverlay(root,true)){var settings=new HelperSettings(owner,null,null,uiService);try{settings.VerifyVisualMenu(root);}finally{settings.Close();}}
        Require(Same(bytes,File.ReadAllBytes(config)),"Menu construction, choices and localization never apply game changes");Require(Directory.GetFiles(folder,"*.tmp",SearchOption.AllDirectories).Length==0,"Atomic writes leave no temp files");
        File.WriteAllText(Path.Combine(root,"visual-tweaks-test.txt"),"PASS: default outline on with explicit apply and no forced renderer mode; four original effects retain defaults; no-op; five independent overrides; outline SystemSettings scope; legacy backup compatibility; scoped duplicate and comment handling; unrelated keys/DLSS/FSR/dithering preservation; UTF8/BOM/UTF16/ANSI and newline preservation; missing-section append; no quality invented on enable; snapshot conflict detection; writable file; game-running/late-start/concurrent-change blocking; verified backups and byte-exact/merged restore; external managed edits and corrupted backup rejection; Steam/non-Steam bounded discovery/manual fallback; explicit-apply EN/ES menu rendered. Only private fixtures changed. Actual Aion visual effects still require live testing after restart.");
    }
}
